/**
 * GoCardless gateway adapter — ported from the EdgePay gateway suite
 * GENERATED by scripts/port-gateways/generate.py — regenerate, do not hand-edit.
 * Flow: rest.
 * PORT-NOTE: sandbox "simulation" fallback (SIM_/uniqid fake success) stripped — API failure now throws.
 */

import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { hmacHex, timingSafeEqual } from '../../lib/hash';

const SLUG = "gocardless";

export class GocardlessGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "GoCardless",
      slug: "gocardless",
      version: '1.0.0',
      description: "GoCardless direct debit integration for EdgePay",
      author: 'EdgePay Gateway Suite (AGPLv3)',
      type: 'gateway',
      supported_currencies: [],
      capabilities: ["verification", "webhook"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "access_token", label: "Access Token", type: "text" as const, required: true },
      { name: "webhook_secret", label: "Webhook Secret", type: "text" as const, required: true },
    ];
  }

  async initiate(_params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const mode = String(credentials.mode ?? 'sandbox');
    const baseUrl = (String(mode) === String("live")) ? ("https://api.gocardless.com") : ("https://api-sandbox.gocardless.com");
    const billingRequestId = "";
    const redirectUrl = "";
    const res = await gwJson({
      url: `${String(baseUrl)}/billing_requests`,
      method: 'GET',
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    return {
          redirect_url: (redirectUrl || undefined) as string | undefined,
          session_id: (billingRequestId || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, _credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["_op_webhook_verified"] ?? '') !== 'true') {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    // PORT-NOTE: upstream verifies via the callback payload only (no
    // server-side API); the unguessable checkout callback token is the
    // authenticity gate for this flow.
    const ok = String(cb["billing_request_id"] ?? cb["session_id"]) !== String("");
    return {
          success: ok,
          gateway_trx_id: String(cb["billing_request_id"] ?? cb["session_id"] ?? ''),
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
      amount: null,
        };
  }

  async verifyWebhook(input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    const credentials = input.credentials;
    const secret = credentials["webhook_secret"] ?? '';
    if (secret === '') return false; // fail-closed
    const provided = input.headers["webhook-signature"] ?? '';
    if (provided === '') return false;
    const expected = await hmacHex('SHA-256', input.rawBody, secret);
    return timingSafeEqual(expected, provided);
  }
}
